class Solution {
public:
    string splitLoopedString(vector<string>& strs) {
        int n = strs.size();
        vector<string> s_arr(n);
        for (int i = 0; i < n; i++) {
            string rev = strs[i];
            reverse(rev.begin(), rev.end());
            s_arr[i] = max(strs[i], rev);
        }

        string best = "";
        for (int i = 0; i < n; i++) {
            string mid = "";
            for (int k = i + 1; k < n; k++) mid += s_arr[k];
            for (int k = 0; k < i; k++) mid += s_arr[k];

            string rev = strs[i];
            reverse(rev.begin(), rev.end());
            vector<string> versions = {strs[i], rev};

            for (const string& cur : versions) {
                int len = cur.size();
                for (int j = 0; j < len; j++) {
                    string cand = cur.substr(j) + mid + cur.substr(0, j);
                    if (cand > best) {
                        best = cand;
                    }
                }
            }
        }
        return best;
    }
};

class Solution {
    public String splitLoopedString(String[] strs) {
        int n = strs.length;
        String[] sArr = new String[n];
        for (int i = 0; i < n; i++) {
            String rev = new StringBuilder(strs[i]).reverse().toString();
            sArr[i] = strs[i].compareTo(rev) >= 0 ? strs[i] : rev;
        }

        String best = "";
        for (int i = 0; i < n; i++) {
            StringBuilder midSb = new StringBuilder();
            for (int k = i + 1; k < n; k++) midSb.append(sArr[k]);
            for (int k = 0; k < i; k++) midSb.append(sArr[k]);
            String mid = midSb.toString();

            String rev = new StringBuilder(strs[i]).reverse().toString();
            String[] versions = {strs[i], rev};

            for (String cur : versions) {
                int len = cur.length();
                for (int j = 0; j < len; j++) {
                    String cand = cur.substring(j) + mid + cur.substring(0, j);
                    if (best.isEmpty() || cand.compareTo(best) > 0) {
                        best = cand;
                    }
                }
            }
        }
        return best;
    }
}

