var splitLoopedString = function(strs) {
    const n = strs.length;
    const sArr = strs.map(s => {
        const rev = s.split('').reverse().join('');
        return s >= rev ? s : rev;
    });

    let best = '';
    for (let i = 0; i < n; i++) {
        let mid = '';
        for (let k = i + 1; k < n; k++) mid += sArr[k];
        for (let k = 0; k < i; k++) mid += sArr[k];

        const rev = strs[i].split('').reverse().join('');
        const versions = [strs[i], rev];

        for (const cur of versions) {
            for (let j = 0; j < cur.length; j++) {
                const cand = cur.slice(j) + mid + cur.slice(0, j);
                if (cand > best) {
                    best = cand;
                }
            }
        }
    }
    return best;
};
